values
  ('39113c9f-7530-5db6-8572-ebd4aa2ce690', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the passage?$q$, $q$[{"text":"Chess is a game that is best played slowly by quiet and careful people.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Younger players are usually more skilled than the older players they face.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"A loss that is examined honestly can teach more than an easy string of wins.","is_correct":true},{"text":"Winning many games in a row is the main purpose of joining a chess club.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$A loss that is examined honestly can teach more than an easy string of wins.$q$, $q$Tomas learns nothing from eleven wins but fills six pages studying one loss, and he keeps learning from Lin afterward. The chess choice names the activity, not the message the story develops about it.$q$, 'draft', 'c542e562-63e4-56f5-9fec-55eb5210faad')
