  ('f584b8c6-884b-545e-8027-65ffa9c2c37c', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the passage?$q$, $q$[{"text":"The quiet efforts of ordinary people are worth remembering and can shape other lives.","is_correct":true},{"text":"Old schoolhouses were cold, smoky, and uncomfortable places to learn.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Only the papers of famous leaders are worth saving for the future.","is_correct":false,"misconception_token":"opposite-of-theme"},{"text":"Historical societies need more volunteers to type up their old letters.","is_correct":false,"misconception_token":"topic-not-theme"}]$q$::jsonb, $q$The quiet efforts of ordinary people are worth remembering and can shape other lives.$q$, $q$Ida Marsh's small sacrifices, like the globe, change a student's life, and Amara comes to value records she first found dull. The smoky stove is one detail, not the story's message.$q$, 'draft', '113f0458-6fc3-5ad7-bddb-576dc8559945')
