values
  ('e133d67a-d59e-5db3-af96-723e92e5ebc6', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'medium',
   $q$Why does the author describe the first three letters, which ask for chalk and complain about the stove?$q$, $q$[{"text":"To show Amara's early boredom, which sets up her later change in how she values the letters.","is_correct":true},{"text":"To explain why the historical society had stored the letters in a box.","is_correct":false,"misconception_token":"misses-purpose"},{"text":"To show that Ida Marsh was a poor teacher who complained too much.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To prove that schools in the early 1900s never had enough money for supplies.","is_correct":false,"misconception_token":"overgeneralization"}]$q$::jsonb, $q$To show Amara's early boredom, which sets up her later change in how she values the letters.$q$, $q$The repeated requests make Amara "check the clock often," so her later interest stands out as a change. Ida writes "politely" and cares for her students, so calling her a poor teacher is unsupported.$q$, 'draft', '113f0458-6fc3-5ad7-bddb-576dc8559945')
