  ('8e5a0c2d-11ad-59ce-aa98-d56a77aef562', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'hard',
   $q$What does Amara's final question, "What's in Box 15?", suggest about how the theme has developed?$q$, $q$[{"text":"She now sees value in ordinary records and wants to read more of them.","is_correct":true},{"text":"She hopes to find more letters written by Walter Pike about his travels.","is_correct":false,"misconception_token":"too-narrow"},{"text":"She is still bored and hopes the next box will finally hold a famous speech.","is_correct":false,"misconception_token":"misreads-ending"},{"text":"She wants to impress Mr. Halvorsen so that he will offer her a paid job.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$She now sees value in ordinary records and wants to read more of them.$q$, $q$Offered "something more exciting," she turns instead to the next box of ordinary records, showing her changed view. The tempting reading that she is still bored ignores that she passes up the chance at something more exciting.$q$, 'draft', '113f0458-6fc3-5ad7-bddb-576dc8559945')
