  ('c09b6e41-7d65-5f37-9856-2bfc01391e18', null, (select id from public.skills where slug = 'read-g9-theme-summary'), null, 'medium',
   $q$How does the comparison between folding dough and folding "my shirts on Sundays" help develop the theme?$q$, $q$[{"text":"It shows that the father is too tired to tell the difference between his two jobs.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"It explains that the bakery is closed on Sundays so the father can rest.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It links his work at the bakery to his care at home, showing the same patient attention in both.","is_correct":true},{"text":"It suggests that the father would rather do laundry than work at the bakery.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It links his work at the bakery to his care at home, showing the same patient attention in both.$q$, $q$Both kinds of folding are done "without hurry," which connects his bakery work to the way he cares for his family. Nothing in the poem says he prefers laundry or is too tired to notice.$q$, 'draft', 'e1083313-f281-5516-b4ab-a092af8eabbf')
