-- Passage rg9-word-parts-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('010113db-f97d-53bd-893b-4116d3ab8a16', 'rg9-word-parts-p06', (select id from public.skills where slug = 'read-g9-word-parts'), null,
        '9-12', $q$Tuning the Hall$q$, $q$The night before the winter concert, the orchestra held its last rehearsal in the old auditorium on Delmar Street. Priya had played the cello for three years, but she had never performed in a room this large, and when she drew her bow across the open strings, the sound seemed to vanish into the high ceiling.

Ms. Abernathy, the conductor, tapped her stand. "Again, please. All the strings together." This time the whole section played in unison, every instrument on the same note at the same moment, and the sound filled the hall instead of drifting away.

They moved on to the slow movement. Ms. Abernathy had arranged it herself, and the parts were copied from her own manuscript, the notes inked by hand in her careful, slanted writing. Near the end, the violins and cellos were supposed to hold a chord while the basses slid underneath. Instead, something sounded wrong: a sour, dissonant clash, like two people singing different songs at once.

The conductor stopped them. A viola player had misread a smudged note. Ms. Abernathy fixed it with a pencil, and they tried again.

This time, the chord seemed to resonate through the whole room, ringing off the wooden walls and lingering in the air after the bows had stopped. Nobody moved. Priya could still feel it humming in the body of her cello.

At the very end, the low brass entered with a deep, sonorous tone that made the floor seem to tremble. Ms. Abernathy lowered her arms and smiled for the first time all evening. "That," she said, "is what we came here to find."$q$, 'draft')
