  ('eaed6800-611f-5be7-acd3-cdbc543c9957', null, (select id from public.skills where slug = 'read-g10-argument-evidence'), null, 'easy',
   $q$Which evidence shows that the canal's decline began before the drought?$q$, $q$[{"text":"The canal carried coal, grain and lumber for 140 miles.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"The upper canal closed for about two months in the summer of 1871.","is_correct":false,"misconception_token":"mismatched-reason"},{"text":"Autumn rains refilled the canal so boats could travel again.","is_correct":false,"misconception_token":"mismatched-reason"},{"text":"Cargo began falling in 1858 and was under half its peak by 1870.","is_correct":true}]$q$::jsonb, $q$Cargo began falling in 1858 and was under half its peak by 1870.$q$, $q$The ledgers show cargo falling from 1858 and reaching 160,000 tons in 1870, "the year before the drought." The two-month closure describes the drought itself, not the earlier decline.$q$, 'draft', 'b116a008-5aaa-5731-ac44-593527db3f0b')
