values
  ('a0db1a1e-262e-528d-aac7-3ee75efd83ef', null, (select id from public.skills where slug = 'read-g10-character-setting-plot'), null, 'hard',
   $q$How do the actions of both birds in the last two paragraphs develop the fable's theme?$q$, $q$[{"text":"The heron's slow flight shows that patience always wins, and the kingfisher's waiting proves it was wrong to hurry.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The heron finally beats the kingfisher at fishing, showing that pride is useful when animals compete for food.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The kingfisher forces the heron to move, showing that the strong should make decisions for those who are weaker.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The heron sets aside its pride to accept help, and the kingfisher welcomes it without gloating, showing that refusing help only leads to loss.","is_correct":true}]$q$::jsonb, $q$The heron sets aside its pride to accept help, and the kingfisher welcomes it without gloating, showing that refusing help only leads to loss.$q$, $q$The heron's pride nearly starves it before it flies upstream, and the kingfisher's quiet welcome matches the moral about pride that refuses help. The kingfisher "flew off without argument," so it never forces anything.$q$, 'draft', '70a8f531-992f-5c7d-9e65-b26e8767e4a4')
